insert into public.ldbc_site_content (id,value) values ('hero-intro','Nơi kết nối, chia sẻ và cùng nhau phát triển của những doanh nhân mang dòng họ Lê trên mảnh đất Tây Nguyên hùng vĩ.') on conflict (id) do nothing;
insert into public.ldbc_site_content (id,value) values ('about-title','Đoàn kết dòng họ —
insert into public.ldbc_site_content (id,value) values ('about-quote','"Với tinh thần Tự hào truyền thống, kiến tạo tương lai và Bản lĩnh vững vàng, vươn tới thịnh vượng, chúng tôi cùng nhau xây dựng mạng lưới kinh doanh Họ Lê vững mạnh trên đất Tây Nguyên."') on conflict (id) do nothing;
insert into public.ldbc_site_content (id,value) values ('about-intro','Câu lạc bộ Doanh nhân Họ Lê Đắk Lắk là thành viên của CLB Doanh nhân Họ Lê Việt Nam — tổ chức trực thuộc Hội đồng Họ Lê Việt Nam. Chúng tôi hoạt động theo tinh thần tương thân tương ái, cùng nhau phát triển kinh doanh và gìn giữ truyền thống dòng tộc.') on conflict (id) do nothing;
insert into public.ldbc_site_content (id,value) values ('join-title','Trở Thành Thành Viên
insert into public.ldbc_site_content (id,value) values ('join-intro','Cùng chúng tôi xây dựng mạng lưới doanh nhân Họ Lê vững mạnh — nơi mỗi thành viên được kết nối, hỗ trợ và cùng nhau phát triển dưới tinh thần "Đoàn kết – Phát triển – Rạng danh Lê tộc Việt Nam".') on conflict (id) do nothing;
